/**
 * Returns Catholic/CEI saint commemorations for a given date.
 * Every saint is returned in their OWN container object.
 * @param {Date|string} date
 * @param {string} lang
 * @returns {Array}
 */
export function getCatholicSaintsForDate(date, lang = 'it') {
  let m, d;
  if (date instanceof Date) {
    m = date.getMonth() + 1;
    d = date.getDate();
  } else if (typeof date === 'string') {
    const parts = date.split(/[-/]/);
    if (parts.length >= 2) {
      m = parseInt(parts[0], 10);
      d = parseInt(parts[1], 10);
    }
  }
  if (!m || !d) {
    const now = new Date();
    m = now.getMonth() + 1;
    d = now.getDate();
  }
  const key = `${m}-${d}`;
  const rawList = CATHOLIC_SAINTS_CALENDAR[key] || [];

  return rawList.map(raw => {
    const saintName = raw[`name_${lang}`] || (lang === 'en' ? raw.name : (raw.name_it || raw.name));
    const saintTitle = raw[`title_${lang}`] || (lang === 'en' ? raw.title : (raw.title_it || raw.title));
    const saintQuote = raw[`quote_${lang}`] || (lang === 'en' ? raw.quote : (raw.quote_it || raw.quote));
    const saintBio = raw[`bio_${lang}`] || (lang === 'en' ? raw.bio : (raw.bio_it || raw.bio));

    return {
      ...raw,
      name: saintName,
      title: saintTitle,
      quote: saintQuote,
      bio: saintBio,
      dateStr: `${m}/${d}`
    };
  });
}

// Backward compatibility helper
export function getCatholicSaintForDate(date, lang = 'it') {
  const list = getCatholicSaintsForDate(date, lang);
  return list && list.length > 0 ? list[0] : null;
}

